A.b7f=new B.e(3,"Do they live near here?","","\uadf8\ub4e4\uc740 \uc774 \uadfc\ucc98\uc5d0 \uc0b4\uc544\uc694?","Do",A.O5)
A.beL=new B.e(4,"Does your mom work on Saturday?","","\uc5b4\uba38\ub2c8\ub294 \ud1a0\uc694\uc77c\uc5d0 \uc77c\ud558\uc138\uc694?","Does",A.O4)
A.ba4=new B.e(5,"Do we need an umbrella?","","\uc6b0\ub9ac \uc6b0\uc0b0\uc774 \ud544\uc694\ud574\uc694?","Do",A.O5)
A.dFi=s([A.bfJ,A.b7f,A.beL,A.ba4],t.k)
A.cXA=s(["will drink","would drink","drinking"],t.s)
A.bez=new B.e(2,u.gh,"","\ubc24\uc5d0 \ucee4\ud53c\ub97c \ub9c8\uc2dc\uba74 \uc7a0\uc744 \ubabb \uc790\uc694.","drink",A.cXA)
A.dyx=s(["will heat","would heat","heats"],t.s)
